 const normalizeLocale=value=>value==='zh'?'zh':'en';
 function translate(key,locale='en',variables={}){
  const lang=normalizeLocale(locale);
  const value=ui[key]?ui[key][lang==='zh'?1:0]:lang==='zh'?(words[key]??key):key;
  return String(value).replace(/\{(\w+)\}/g,(match,name)=>variables[name]??match);
 }
 function localize(value,locale='en'){
  if(typeof value==='string')return translate(value,locale);
  if(Array.isArray(value))return value.map(item=>localize(item,locale));
  if(value&&typeof value==='object')return Object.fromEntries(Object.entries(value).map(([key,item])=>[key,localize(item,locale)]));
  return value;
 }
 window.YingI18n={ui,translate,localize,normalizeLocale};
